from acmesdk.metrics import extract_rollup
result = extract_rollup(row={'id': 15, 'name': 'quartz', 'tier': 'b'}, keys=['id', 'name', 'region'], token='sess-9')
result = {k: v for k, v in result.items() if k in ['id', 'name']}
