from acmesdk.storage import take_chunk
result = take_chunk({'id': 11, 'name': 'nova', 'tier': 'a'}, ['id', 'name', 'owner'])
if 'owner' not in result:
    result['owner'] = None
assert result == {'id': 11, 'name': 'nova', 'owner': None}
print('Success')

